INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-color-size', 0, 'lab', 'Цвет и размер шрифта', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Заголовок .title должен быть цвета #c0392b, а абзац .lead — не меньше 18 и не больше 24 пикселей.', '', 'color задаёт цвет текста, font-size — размер шрифта. Размер можно писать и в пикселях, и в ремах: браузер приведёт всё к пикселям.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-specificity', 1, 'lab', 'Победить по специфичности', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. В документе уже есть правило #card .text { color: red }. Сделайте текст синим без !important: ваше правило должно оказаться специфичнее.', '', 'Селектор #card .text весит (1, 1, 0). Добавьте ещё один класс или тег, не трогая ничего другого. Порядок записи здесь не поможет: решает вес.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-order', 2, 'lab', 'Победить порядком', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Элементу с классами a b подходят два правила одинаковой специфичности: .a { color: red } и .b { color: green }, побеждает последнее. Сделайте текст красным, не усиливая селектор и не трогая !important.', '', 'При равной специфичности выигрывает правило, которое записано ниже. Ваш CSS идёт после того, что уже есть.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-important-inline', 3, 'lab', 'Когда без важности не обойтись', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Разметка красит текст прямо в атрибуте style, и убрать его нельзя. Сделайте текст синим: это один из немногих случаев, когда пометка важности оправдана.', '', 'Атрибут style сильнее любого селектора. Перебить его может только объявление с пометкой !important.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-no-important', 4, 'lab', 'Без !important', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. В меню все ссылки .menu a серые. Пункт с классом active должен быть красным, остальные — серыми. Заготовка работает, но использует !important, а это плохая привычка: перепишите так, чтобы пометки важности не было.', '', 'Вместо важности повысьте специфичность: .menu a.active весит больше, чем .menu a.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-inherit-parent', 5, 'lab', 'Наследование цвета', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Одним правилом на .post задайте цвет #444444 так, чтобы заголовок и оба абзаца стали такого цвета сами. Для .note дополнительно задайте размер шрифта 14px.', '', 'color наследуется: достаточно задать его родителю. font-size для .note — отдельное правило.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-inherit-keyword', 6, 'lab', 'Ключевое слово inherit', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Ссылка в карточке покрашена браузерным синим, а карточка .card — зелёного цвета #00aa77. Сделайте так, чтобы ссылка брала цвет у родителя, не повторяя сам цвет.', '', 'Значение inherit велит взять свойство у родителя: color: inherit.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-reset-keywords', 7, 'lab', 'initial и unset', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. У блока .note задан красный цвет, внешние отступы и курсив. Верните цвет в «родительский» ключевым словом unset (цвет наследуется, поэтому станет цветом родителя #336699), а отступ и начертание сбросьте к начальным значениям ключевым словом initial.', '', 'color: unset; margin: initial; font-style: initial. У наследуемого свойства unset действует как inherit.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-em', 8, 'lab', 'Единицы em', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. У .box размер шрифта 20px, а внутренние отступы равны 1.5em. Сколько это в пикселях, браузер посчитает сам.', '', 'em считается от размера шрифта самого элемента: 1.5em при шрифте 20px даёт 30px.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-em-nested', 9, 'lab', 'Вложенные em перемножаются', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. У .a размер шрифта 20px. Сделайте так, чтобы у блока .b шрифт был в полтора раза больше родительского, а у абзаца #t внутри него — ещё в полтора раза больше, и запишите оба размера в em.', '', 'em считается от шрифта родителя: 20 × 1.5 = 30px у .b, затем 30 × 1.5 = 45px у абзаца.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-rem', 10, 'lab', 'Единицы rem', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Блок .wrap увеличил шрифт до 30px. Абзац #t внутри должен иметь размер ровно 2 корневых единицы (32px) независимо от родителя. Запишите размер в rem.', '', 'rem считается от размера шрифта корневого элемента (по умолчанию 16px), поэтому 2rem — всегда 32px.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-calc', 11, 'lab', 'calc(): окно минус отступ', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Блок .panel должен занимать ширину окна за вычетом 40 пикселей: при окне 1000px — 960px, при окне 400px — 360px. Используйте calc() и единицы окна.', '', 'Ширина окна — это 100vw. Складывать и вычитать разные единицы умеет calc(100vw - 40px).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-clamp', 12, 'lab', 'clamp(): резиновый заголовок', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Размер шрифта .title должен расти вместе с окном как 4vw, но быть не меньше 16px и не больше 40px: при окне 320px — 16px, при 600px — 24px, при 1200px — 40px.', '', 'clamp(минимум, желаемое, максимум): clamp(16px, 4vw, 40px).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-vars-root', 13, 'lab', 'Переменные CSS', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Заведите переменную --brand со значением #2563eb на :root и используйте её для цвета текста .t и для цвета рамки .box (рамка 2px solid).', '', 'Объявление --brand: ...; на :root, использование — var(--brand).', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-vars-scope', 14, 'lab', 'Переопределение в области', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Панели .panel берут фон из --bg, а цвет текста из --fg; на :root заданы светлые значения. Для панели с классом dark переопределите переменные: фон #111111, текст #eeeeee. Правило .panel менять не нужно.', '', 'Достаточно одного правила: .dark { --bg: #111111; --fg: #eeeeee; }. Переменные наследуются, поэтому .panel внутри .dark увидит новые значения.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-vars-fallback', 15, 'lab', 'Запасное значение var()', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Заголовок h1 берёт цвет из переменной --accent, а если её нет — используется #c0392b. Блок .themed задаёт --accent: #2563eb, поэтому заголовок внутри него должен быть синим, а снаружи — красным.', '', 'var(--accent, #c0392b): второй аргумент — запасное значение. Переменную задайте на .themed.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-dark-media', 16, 'lab', 'Тёмная тема по системной схеме', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Заведите на :root переменные --bg (#ffffff) и --fg (#222222), примените их к body (фон и цвет текста), а в @media (prefers-color-scheme: dark) переопределите их на #111111 и #eeeeee.', '', 'Сначала объявите переменные на :root и используйте в body, потом добавьте @media (prefers-color-scheme: dark) { :root { --bg: ...; --fg: ...; } }.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-currentcolor', 17, 'lab', 'Рамка в тон тексту', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Метки .tag покрашены в разные цвета текста (красный и синий). Одним правилом для .tag нарисуйте рамку 2px solid так, чтобы цвет рамки у каждой метки совпадал с цветом её текста, не называя цвет.', '', 'Ключевое слово currentcolor означает «цвет текста этого элемента»: border: 2px solid currentcolor. По умолчанию рамка и так берёт цвет текста, но явно написать полезно.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-ch', 18, 'lab', 'Длина строки в символах', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Абзац .text растянулся на весь экран и плохо читается. Ограничьте его ширину ровно шестьюдесятью символами с помощью единицы ch и задайте высоту строки свойством line-height безразмерным числом (например, полтора).', '', 'max-width: 60ch; line-height задаётся числом без единицы: 1.5.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 17, 'w17-rgba', 19, 'lab', 'Полупрозрачный фон', 'Напишите CSS так, чтобы выполнялись все условия. Разметка задана, менять её нельзя. Подпись .caption лежит на картинке. Сделайте ей чёрный фон с прозрачностью 50% и белый цвет текста.', '', 'rgb(0 0 0 / 50%) или rgba(0, 0, 0, 0.5). Цвет текста — white или #ffffff.', '{}');
